records=[]
for name in sorted({s for r in roles for s in r['skills']}):
 dest=root/'.agents/skills'/name
 src=pathlib.Path('/Users/gqadonis/Projects/hybrid-mobile-architecture-src/skills')/name
 if not src.exists(): src=pathlib.Path('/Users/gqadonis/.codex/skills')/name
 if not dest.exists():
  if not (src/'SKILL.md').exists(): raise SystemExit(f'Missing skill {name}')
  shutil.copytree(src,dest,symlinks=False,ignore=shutil.ignore_patterns('__pycache__','.DS_Store','node_modules'))
 c=root/'.claude/skills'/name
 if not c.exists(): c.symlink_to(pathlib.Path('../../.agents/skills')/name,target_is_directory=True)
 records.append({'id':name,'source':str(src),'project':str(dest.relative_to(root)),'sha256':hashlib.sha256((dest/'SKILL.md').read_bytes()).hexdigest()})
